function data(){return practiceHome?practiceAccount:account||defaultAccount();}
function toast(text,kind='info'){let container=$('.toasts');if(!container){container=document.createElement('div');container.className='toasts';document.body.append(container);}const el=document.createElement('div');el.className='toast '+kind;el.textContent=text;container.append(el);setTimeout(()=>el.remove(),5500);}
