function progression(before,after){if(!before)return;for(const [id,q]of Object.entries(ISLAND_QUESTS)){if(after.islandQuests?.[id]?.completedAt&&!before.islandQuests?.[id]?.completedAt){audio.play('achievement');feedback.celebrate(q.name+' complete','+'+q.gold+' gold · +'+q.xp+' XP · Progress saved');}}if(level(after.xp)>level(before.xp)){audio.play('levelup');feedback.celebrate('Captain level '+level(after.xp),'New horizons. New unlocks.','level');if(snapshot)renderer?.feedback({type:'levelup',x:snapshot.me.x,y:snapshot.me.y});}if(before.contract&&!after.contract&&after.claims.includes('contract:'+before.contract.instance)){audio.play('achievement');feedback.celebrate('Contract complete','Gold and XP added to your captain.');}}
