async function api(path,body){const {data:{session:s}}=await auth.auth.getSession();if(!s)throw new Error('Sign in to load your captain.');session=s;const r=await fetch(serverURL+'/api/'+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+s.access_token,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15000)});const d=await r.json();if(!r.ok)throw new Error(d.error||'Server request failed.');return d;}
