const logo='<svg viewBox="0 0 24 24" fill="none" stroke="#476275" stroke-width="1.6"><path d="M12 3v14M4 14c0 5 4 7 8 7s8-2 8-7M3 14h4M17 14h4M8 8h8"/><circle cx="12" cy="4" r="2" fill="#ddecf8"/></svg>';
