function openModal(title,description,body,narrow=false,back='close'){keys.clear();pointer.fire=false;dialogBack=back;modal=title;app.inert=true;document.body.classList.add('menu-open');$('#dialog')?.remove();const el=document.createElement('div');el.id='dialog';el.className='overlay';el.innerHTML=`<section class="modal ${narrow?'narrow':''}" role="dialog" aria-modal="true" aria-label="${escape(title)}"><div class="modal-head"><div><span class="eyebrow">Tidebound Pirates</span><h2>${escape(title)}</h2>${description?`<p>${escape(description)}</p>`:''}</div>${button('close','← Back','ghost small',false,'aria-label="Back"')}</div><div class="modal-body">${body}</div></section>`;document.body.append(el);if(gameMode==='solo'||gameMode==='practice')send('pause',true);el.querySelector('button,input')?.focus();}
function closeModal(){if(lessonIntro==='showing'){lessonIntro=false;rememberTraining('skipped');}modal=null;pendingBinding=null;app.inert=false;document.body.classList.remove('menu-open');$('#dialog')?.remove();keys.clear();pointer.fire=false;if(gameMode==='solo'||gameMode==='practice')send('pause',false);if(!gameMode)home();}
