function shop(){if(!requireCaptain())return;openModal('The shipyard','Spend banked gold. Every cosmetic leaves your ship’s combat stats unchanged.',tabs('shop')+`<div class="row spread" style="margin-bottom:18px"><span>◈ ${fmt(data().gold)} banked gold</span><span class="pill">Level ${level(data().xp)}</span></div><div class="items">${itemCards()}</div>`);}
