function trainingKey(){return 'tidebound-training-v2-'+(practiceHome?'practice':session?.user.id||'captain');}
function trainingSeen(){try{return Boolean(localStorage.getItem(trainingKey()));}catch{return false;}}
function rememberTraining(status){try{localStorage.setItem(trainingKey(),status);}catch{}}
function welcomeLesson(){if(!snapshot)return;lessonIntro='showing';const k=a=>`<kbd>${escape(keyLabel(prefs.keys[a]))}</kbd>`;openModal('Welcome aboard','Let’s bring home your first treasure.',`<div class="lesson-welcome"><div class="lesson-emblem" aria-hidden="true">⚓</div><p class="lesson-summary">Sail to a wreck. Collect a chest. Bring it home to bank your gold.</p><div class="intro-controls"><div>${k('anchor')}<span>Raise anchor</span></div><div>${k('sailUp')} ${k('sailDown')}<span>Adjust sails</span></div><div>${k('left')} ${k('right')}<span>Steer</span></div><div>${k('interact')}<span>Search & collect</span></div></div><p>We’ll guide you one step at a time, with a golden marker showing where to go.</p><div class="row wrap">${button('lessonstart','Start sailing lesson','primary')}${button('lessonskip','I know the ropes','ghost')}</div></div>`);}
function startLesson(){if(!snapshot)return;lesson=new FirstVoyage(snapshot.me);lessonIntro=false;closeModal();updateHud();}
function skipLesson(){lesson=null;lessonIntro=false;rememberTraining('skipped');renderer?.setWaypoint(null);closeModal();updateHud();}
function advanceLesson(input,dt){if(lesson?.update(snapshot,input,dt)){lesson=null;rememberTraining('complete');renderer?.setWaypoint(null);toast('First voyage complete! Visit Your harbor to buy upgrades and skins.','success');}}
function settings(back=modal==='Paused'||modal==='Voyage menu'?'pause':'close'){const p=prefs;openModal('Options','Tune the sound, graphics, and controls.',`<form class="form" data-form="settings"><div class="settings-cols"><div>${['master','music','effects'].map(k=>`<label>${k[0].toUpperCase()+k.slice(1)} volume<input name="${k}" type="range" min="0" max="1" step=".05" value="${p[k]}"></label>`).join('')}<label>Graphics quality<select name="quality">${['low','medium','high'].map(q=>`<option ${(qualityOverride||p.quality)===q?'selected':''}>${q}</option>`).join('')}</select></label><label style="display:block;margin-top:16px"><input type="checkbox" name="device" ${qualityOverride?'checked':''}> Graphics quality for this device only</label><label style="display:block;margin-top:16px"><input type="checkbox" name="motion" ${p.reducedMotion?'checked':''}> Reduced motion</label><div class="row wrap" style="margin-top:20px">${button('fullscreen','Fullscreen','small')}${session?button('logout','Log out','small'):''}</div></div><div><h3>Controls</h3><p style="font-size:12px">Select an action, then press its new key. Your handbook and lesson update with your bindings.</p><div class="binds">${Object.entries(p.keys).map(([k,v])=>button('bind',`${escape(bindingNames[k])} <kbd>${escape(keyLabel(v))}</kbd>`,'',false,`data-value="${k}"`)).join('')}</div></div></div><button class="primary">Save options</button><div class="form-error" role="alert"></div></form>`,false,back);}
function openAuth(){if(session){openModal('Your account','Your email is private and is never shown to other captains.',`<p>Signed in. ${escape(saveStatus)}</p>${button('logout','Log out','peach')}`,true);return;}const recovery=authMode==='recovery';openModal('Welcome aboard','Use an account to keep your captain across browsers and devices.',`<div class="auth-tabs">${button('authmode','Sign in',authMode==='signin'?'selected':'',false,'data-value="signin"')}${button('authmode','Create account',authMode==='signup'?'selected':'',false,'data-value="signup"')}</div>${!configured?'<div class="notice-box">Cloud accounts are unavailable on this copy. Offline Practice is playable.</div>':''}<form class="form" data-form="auth" style="margin-top:18px">${authMode==='signup'?'<label>Public pirate name<input name="name" autocomplete="nickname" minlength="2" maxlength="24" required></label>':''}<label>Email<input name="email" type="email" autocomplete="email" required></label>${recovery?'':'<label>Password<input name="password" type="password" autocomplete="'+(authMode==='signup'?'new-password':'current-password')+'" minlength="8" required></label>'}<button class="primary" ${!configured?'disabled':''}>${recovery?'Send recovery email':authMode==='signup'?'Create account':'Sign in'}</button><div class="form-error" role="alert"></div></form>${button('authmode','Forgot your password?','ghost small',!configured,'data-value="recovery"')}`,true);}
function journal(back='close'){
  const d=data();openModal('Island journal','Meet each island’s quest giver, explore on foot, and return with the requested items.',`<div class="island-journal">${ISLANDS.map(i=>{const q=ISLAND_QUESTS[i.id],p=questState(d,i.id),visited=d.visitedIslands?.includes(i.id);return `<article class="journal-entry ${p.done?'quest-done':''}"><span class="eyebrow">${p.done?'Completed':p.accepted?'Quest in progress':visited?'Discovered':'Unexplored'} · ${escape(i.theme)}</span><h3>${escape(i.name)}</h3><p>${escape(i.description)}</p><strong>${escape(q.name)}</strong><small>${escape(i.npc.name)} · ◈ ${q.gold} gold · ${q.xp} XP</small><ul class="quest-checklist">${q.steps.map(step=>`<li class="${p.steps.includes(step.id)?'complete':''}"><span>${p.steps.includes(step.id)?'✓':'◇'}</span> ${escape(step.name)}</li>`).join('')}</ul>${p.accepted&&!p.done&&p.steps.length===p.total?'<p class="quest-ready">Return to the quest giver for your reward.</p>':''}${gameMode?button('trackIsland',snapshot?.me.ashore?.island===i.id?'Explore this island':'Mark landing dock','small',false,`data-value="${i.id}"`):'<small>Set sail and choose this island on your sea chart.</small>'}</article>`;}).join('')}</div>`,false,back);
}
function islandTalk(id){
  const i=islandById(id);if(!i||snapshot?.me.ashore?.island!==id)return;
  const q=ISLAND_QUESTS[id],p=questState(data(),id),ready=p.steps.length===p.total;
  openModal(i.npc.name,i.name,`<div class="quest-dialogue"><span class="quest-seal">✦</span><h3>${escape(q.name)}</h3><p class="npc-quote">“${escape(p.done?q.outro:!p.accepted?q.intro:ready?'You found everything! The island owes you a reward.':'Keep looking, captain. The gold markers will guide you to the missing items.')}”</p><div class="quest-pay">◈ ${q.gold} gold · ${q.xp} XP · ${q.rep} reputation</div>${p.accepted?`<ul class="quest-checklist">${q.steps.map(step=>`<li class="${p.steps.includes(step.id)?'complete':''}">${p.steps.includes(step.id)?'✓':'◇'} ${escape(step.name)}</li>`).join('')}</ul>`:''}<div class="row wrap">${!p.accepted?button('questStart','Accept quest','primary'):!p.done&&ready?button('questFinish','Collect reward','primary'):''}${button('resume',p.done?'Keep exploring':'Back to exploring','ghost')}</div></div>`,true);
}
function map(){if(!snapshot)return;openModal('Sea chart','Choose an island to mark its landing dock. Green waters around Marigold protect new captains.',`<canvas id="large-map" width="760" height="480" class="mapcanvas"></canvas><div class="map-legend">● You &nbsp; × Wrecks &nbsp; ◇ Objective &nbsp; ⚓ Landing docks</div><div class="island-routes">${ISLANDS.map(i=>button('trackIsland',escape(i.name)+(questState(data(),i.id).done?' ✓':''),courseIsland===i.id?'selected small':'small',false,`data-value="${i.id}"`)).join('')}</div><div class="objective" style="margin-top:15px">Treasure clue: ${escape(ISLANDS[snapshot.me.clue]?.clue||'Search a shipwreck.')}<br>At an island’s dock, stop and click <strong>Go ashore</strong> to explore and find quests.</div>`);drawMap($('#large-map'),true);}
function cargo(){if(!snapshot)return;const me=snapshot.me;openModal('Your hold','This treasure is unbanked. Sinking drops it into the ocean.',`<div class="row spread" style="margin-bottom:20px"><span>${me.cargo.reduce((n,i)=>n+i.size,0)} / ${me.capacity} slots</span><strong>◈ ${fmt(me.cargo.reduce((n,i)=>n+i.value,0))} at risk</strong></div><div class="stack">${me.cargo.length?me.cargo.map(i=>`<div class="cargo-row"><div><strong>${escape(i.name)}</strong><br><small>${i.size} slots · ◈ ${fmt(i.value)}</small></div>${i.type!=='mail'?button('discard','Discard','small',false,`data-value="${i.id}"`):'<span class="pill">Contract cargo</span>'}</div>`).join(''):'<p>An empty hold. Find treasure or salvage a wreck.</p>'}</div>`);}
function fleet(){if(gameMode!=='online'){toast('Fleets belong to online voyages.');return;}const f=snapshot.fleet;openModal('Sail together','Four captains per fleet. Friendly fire is disabled and nearby NPC objectives count for each member.',f?`<div class="objective">Fleet code: <strong>${escape(f.code)}</strong></div><div class="stack" style="margin-top:18px">${f.members.map(m=>`<div class="leader-row"><span>${escape(m.name)} ${m.id===f.leader?'· leader':''}</span>${f.leader===playerId&&m.id!==playerId?button('fleetkick','Remove','small',false,`data-value="${m.id}"`):''}</div>`).join('')}${f.pending.map(m=>`<div class="leader-row"><span>${escape(m.name)} wants to join</span>${button('fleetaccept','Accept','mint small',false,`data-value="${m.id}"`)}</div>`).join('')}${button('fleetleave','Leave fleet','peach')}</div>`:`<p>Create a fleet and share its code with a captain in this same ocean.</p>${button('fleetcreate','Create fleet','mint')}<form data-form="fleet" class="form" style="margin-top:20px"><label>Fleet code<input name="code" maxlength="6" required></label><button class="primary">Request to join</button></form>`);}
function send(type,value){if(type==='land'){if(snapshot?.me.ashore)type='board';else if(snapshot&&!snapshot.me.anchor&&nearbyDock(snapshot.me))type='anchor';else{type='disembark';if(lesson){lesson=null;rememberTraining('skipped');}}}if(type==='interact'&&snapshot&&interactionHint(snapshot).stop&&!snapshot.me.anchor)type='anchor';if(world)world.action(playerId,type,value);else room?.send('action',{type,value});}
function sound(event){if(!snapshot)return;const view=snapshot.me.ashore||snapshot.me,distance=dist(view,event);if(distance>850)return;audio.play(event.type,{gain:Math.max(.12,1-distance/850),pan:Math.max(-.8,Math.min(.8,(event.x-view.x)/450)),heavy:event.heavy});renderer?.feedback(event);if(event.type==='queststep'&&event.id===playerId)feedback.label('Objective saved',renderer?.project(event.x,event.y),'quest');if(event.type==='loot'&&event.id===playerId)feedback.label('+'+fmt(event.value)+' gold in hold',renderer?.project(event.x,event.y));if(event.type==='impact'&&event.id===playerId){feedback.damageUntil=performance.now()+500;feedback.label('−'+fmt(event.amount)+' hull',renderer?.project(event.x,event.y),'damage');}else if(event.type==='impact'&&event.owner===playerId){hitUntil=performance.now()+220;feedback.label('Hit −'+fmt(event.amount),renderer?.project(event.x,event.y),'hit');}}
function explosion(event){if(!snapshot||dist(snapshot.me,event)>850)return;renderer?.explosion(event.x,event.y);audio.play('explosion',{gain:Math.max(.15,1-dist(snapshot.me,event)/850)});}
async function play(mode){if(loading)return;if(mode!=='practice'&&(!account||!configured))return;loading=true;closeModal();keys.clear();pointer.fire=false;audio.start();practiceHome=mode==='practice';prefs=data().preferences;audio.configure(prefs);feedback.configure(prefs);audio.setScene('voyage');gameMode=mode;courseIsland=null;lesson=null;snapshot=null;lessonIntro=mode!=='online'&&(forceLesson||!trainingSeen());forceLesson=false;saveStatus=practiceHome?'Local practice':'Cloud save confirmed';playerId=uid();app.innerHTML='<div class="loading"><div class="spinner"></div><p>Finding your patch of ocean…</p></div>';
  try{if(practiceHome){prefs=practiceAccount.preferences;world=new World('practice',{notice:(s,t,k)=>toast(t,k),reward:async(s,r)=>{const previous=practiceAccount;practiceAccount=applyReward(practiceAccount,r);progression(previous,practiceAccount);localSave();return practiceAccount;},bank:async(s,items,gold)=>{const previous=practiceAccount;practiceAccount=applyReward(practiceAccount,{type:'bank',mode:'practice',ship:s.kind,gold,items:items.length});progression(previous,practiceAccount);localSave();return practiceAccount;},result:(s,r)=>result(r),sound:(s,type,detail)=>sound({...detail,type}),explosion:s=>explosion({id:s.id,x:s.x,y:s.y})});world.addPlayer(playerId,practiceAccount);snapshot=world.snapshot(playerId);connection='Offline practice';beginOcean();}
    else {connection='Connecting…';const r=mode==='solo'?await network.create('solo',{token:session.access_token}):await network.joinOrCreate('ocean',{token:session.access_token});attachRoom(r);beginOcean();}
  }catch(e){gameMode=null;lessonIntro=false;toast(e.message,'error');home('title');}finally{loading=false;}}
function beginOcean(){app.innerHTML='<div class="game"><div id="ocean"></div><div class="hud" id="hud"></div><div class="reticle"></div></div>';try{renderer ||=new OceanRenderer($('#ocean'));if(!renderer.renderer.domElement.isConnected)$('#ocean').append(renderer.renderer.domElement);renderer.configure(graphics(prefs));if(snapshot)renderer.sync(snapshot,playerId);}catch(e){toast('WebGL could not start. Try a browser with hardware acceleration.','error');world=null;lessonIntro=false;gameMode=null;if(room){const old=room;room=null;old.leave();sessionStorage.removeItem('tidebound-reconnect');}home('title');return;}hud=new VoyageHud($('#hud'));aimIntent={aim:0,target:null};updateHud();if(snapshot&&lessonIntro)welcomeLesson();}
function attachRoom(r){room=r;world=null;playerId=r.sessionId;connection='Connected';gameMode=gameMode||'online';sessionStorage.setItem('tidebound-reconnect',JSON.stringify({token:r.reconnectionToken,at:Date.now(),user:session.user.id,mode:gameMode}));r.onMessage('welcome',v=>{gameMode=v.mode;});r.onMessage('snapshot',v=>{snapshot=v;renderer?.sync(v,playerId);if(lessonIntro===true&&$('#ocean'))welcomeLesson();});r.onMessage('account',d=>setAccount(d));r.onMessage('notice',v=>toast(v.text,v.kind));r.onMessage('result',result);r.onMessage('sound',sound);r.onMessage('explosion',explosion);r.onMessage('pong',v=>ping=Date.now()-v);r.onMessage('finished',()=>{const old=room;room=null;sessionStorage.removeItem('tidebound-reconnect');old?.leave();closeModal();snapshot=null;gameMode=null;lesson=null;home('harbor');});r.onError((code,message)=>toast(message||'Connection error.','error'));r.onLeave(code=>{if(room!==r)return;room=null;if(code===1000){gameMode=null;sessionStorage.removeItem('tidebound-reconnect');home('title');}else reconnect(r.reconnectionToken);});}
async function reconnect(token){connection='Reconnecting · ship remains at risk';const until=Date.now()+30000;let recovered=false;while(Date.now()<until&&gameMode){try{const r=await network.reconnect(token);attachRoom(r);recovered=true;toast('Reconnected to your current ship.','success');break;}catch{await new Promise(resolve=>setTimeout(resolve,1000));}}if(!recovered){sessionStorage.removeItem('tidebound-reconnect');snapshot=null;gameMode=null;home();toast('The unfinished voyage ended. Committed progression is safe; unbanked cargo is lost.','error');try{await loadAccount();}catch{}}}
function objective(){const s=snapshot.me;if(s.ashore)return shoreObjective(data(),s.ashore);if(lesson)return lesson.objective(snapshot,prefs.keys);const k=a=>keyLabel(prefs.keys[a]),loot=snapshot.loot.find(i=>dist(i,s)<80);if(s.search)return {title:'Searching…',body:'Keep the anchor lowered until your treasure appears.',progress:1-s.search.time/3};if(loot)return {title:'Treasure within reach',body:`Press ${k('interact')} to bring ${loot.name} aboard.`};if(s.cargo.some(i=>i.type!=='mail'))return {title:'Bring your haul home',body:`Return to harbor, lower sails, anchor, and press ${k('interact')} to bank.`,target:PORT};const dock=nearbyDock(s);if(dock)return {title:'Explore '+dock.island.name,body:'Stop at the dock and click Go ashore. '+dock.island.npc.name+' has an island quest for you.',target:dock.point};if(courseIsland){const i=islandById(courseIsland);return {title:'Sail to '+i.name,body:'Follow the anchor marker. Stop at the landing dock, then click Go ashore.',target:dockPoint(i)};}return {title:s.anchor?'Ready to sail?':'Discover new islands',body:s.anchor?`Hold ${k('sailUp')} to set sail. Press ${k('anchor')} to stop and lower anchor.`:`Open ${k('map')} to mark an island dock, or find a wreck. Each island has a character and a quest to explore on foot.`};}
function updateHud(){if(!snapshot||!$('#hud')||!hud)return;const goal=objective(),target=snapshot.ships.find(s=>s.id===aimIntent.target)||null,status=aimStatus(snapshot.me,target,gameMode);renderer?.setWaypoint(goal.target?{...goal.target,land:Boolean(snapshot.me.ashore)}:null);hud.update({state:snapshot,account:data(),mode:gameMode,prefs,goal,lesson,target,status,ping,damage:feedback.damageUntil>performance.now()});drawMap($('#minimap'),false);}
function updateAim(){if(!snapshot||!renderer)return;$('.reticle')?.classList.toggle('hidden',Boolean(snapshot.me.ashore));if(snapshot.me.ashore){aimIntent={aim:0,target:null};renderer.setTarget(null);return;}aimIntent=renderer.aimAt(pointer.x,pointer.y);const target=snapshot.ships.find(s=>s.id===aimIntent.target)||null;aimFeedback=aimStatus(snapshot.me,target,gameMode);renderer.setTarget(aimIntent.target,aimFeedback);const reticle=$('.reticle');if(reticle){reticle.classList.toggle('locked',Boolean(target));reticle.classList.toggle('blocked',Boolean(target)&&!aimFeedback.ok);reticle.classList.toggle('hit',performance.now()<hitUntil);}}

function drawMap(canvas,large){
  if(!canvas||!snapshot)return;const c=canvas.getContext('2d');if(!c)return;
  const w=canvas.width,h=canvas.height,local=!large&&snapshot.me.ashore,focus=local?islandById(snapshot.me.ashore.island):{x:0,y:0},scale=local?Math.min(w,h)/(focus.r*2.4):Math.min((w-26)/(WORLD.maxX-WORLD.minX),(h-26)/(WORLD.maxY-WORLD.minY)),x=v=>w/2+(v-focus.x)*scale,y=v=>h/2+(v-focus.y)*scale;
  c.fillStyle='#bfd7ce';c.fillRect(0,0,w,h);c.setLineDash([3,4]);c.strokeStyle='#80a181';c.lineWidth=large?2:1;c.beginPath();c.arc(x(PORT.x),y(PORT.y),BALANCE.beginnerRadius*scale,0,Math.PI*2);c.stroke();c.setLineDash([]);
  for(const i of ISLANDS){c.fillStyle='#'+i.color.toString(16).padStart(6,'0');c.strokeStyle=i.theme==='volcanic'?'#aaa58a':'#ecd6aa';c.lineWidth=large?3:1;c.beginPath();islandOutline(i).forEach((p,n)=>{if(n)c.lineTo(x(p.x),y(p.y));else c.moveTo(x(p.x),y(p.y));});c.closePath();c.fill();c.stroke();const dock=dockPoint(i);c.fillStyle='#6b674b';c.font=(large?'14':'9')+'px system-ui';c.fillText('⚓',x(dock.x)-4,y(dock.y)+4);if(large){c.font='12px system-ui';c.fillStyle='#29433f';c.fillText(i.name,x(i.x)+i.r*scale+7,y(i.y));}}
  if(local){const i=focus,p=questState(data(),i.id);for(const step of ISLAND_QUESTS[i.id].steps)if(p.accepted&&!p.steps.includes(step.id)){const point=localPoint(i,step);c.fillStyle='#b68c34';c.beginPath();c.arc(x(point.x),y(point.y),3,0,Math.PI*2);c.fill();}const npc=localPoint(i,i.npc);c.fillStyle='#866140';c.fillText('!',x(npc.x)-2,y(npc.y)+3);const ship=landingPoint(i);c.fillText('⚓',x(ship.x)-4,y(ship.y)+3);}
  for(const r of WRECKS){c.fillStyle='#516b61';c.font=(large?'18':'10')+'px system-ui';c.fillText('×',x(r.x)-3,y(r.y)+3);}
  const target=objective().target;if(target){c.strokeStyle='#b58b32';c.lineWidth=large?3:2;c.beginPath();c.arc(x(target.x),y(target.y),large?10:5,0,Math.PI*2);c.stroke();}
  for(const s of snapshot.ships){if(s.id!==playerId&&dist(s,snapshot.me.ashore||snapshot.me)>650&&!(s.fleet&&s.fleet===snapshot.me.fleet))continue;const p=s.id===playerId?snapshot.me.ashore||s:s;c.fillStyle=s.id===playerId?'#2f5063':s.fleet&&s.fleet===snapshot.me.fleet?'#528958':s.npc?'#a38364':'#ae7163';c.beginPath();c.arc(x(p.x),y(p.y),s.id===playerId?4:2.5,0,Math.PI*2);c.fill();}
  if(!local&&snapshot.greed.ping){c.strokeStyle='#b18538';c.beginPath();c.arc(x(snapshot.greed.ping.x),y(snapshot.greed.ping.y),large?14:6,0,Math.PI*2);c.stroke();}
}
function result(r){if(r.kind==='islandTalk'){islandTalk(r.island);return;}if(r.kind==='bank'&&lesson){lesson.banked=true;advanceLesson({},0);}openModal(r.kind==='bank'?'Treasure banked!':'Ship sunk',r.kind==='bank'?'Your gold is safe. Spend it on your next adventure.':'Your unbanked treasure dropped into the ocean. Your owned ship and banked gold are safe.',`<div class="result-number">${r.kind==='bank'?'◈ '+fmt(r.gold):'⚓'}</div><p>${r.kind==='bank'?`${r.items} treasures banked · ${r.xp} XP earned.`:`${r.lost||0} cargo items lost. You are back at Marigold Harbor.`}</p><div class="row">${button('close',r.kind==='bank'?'Keep sailing':'Sail again','primary')}${button('finish','Your harbor','mint')}</div>`,true);if(r.kind==='bank'){audio.play('bank');feedback.bank($('.result-number'),r.gold);if(snapshot)renderer?.feedback({type:'bank',x:snapshot.me.x,y:snapshot.me.y});}}
async function finish(){if(world){world=null;practiceAccount=applyAction(practiceAccount,{type:'abandonContract'});lesson=null;lessonIntro=false;closeModal();snapshot=null;gameMode=null;localSave();home('harbor');}else if(room){if(snapshot&&dist(snapshot.me,PORT)<BALANCE.safeRadius&&snapshot.me.cargo.every(i=>i.type==='mail'))room.send('finish');else openModal('End this voyage?','Unbanked cargo will be dropped. Your ship stays in the ocean for 30 seconds after leaving.',`${button('abandonvoyage','Leave and lose this cargo','peach')}`,true);}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;audio.play('ui');const a=b.dataset.action,v=b.dataset.value;try{
  if(a==='close')backFromModal();if(a==='resume')closeModal();if(['title','voyages','harbor'].includes(a))home(a);if(a==='solo'||a==='online'||a==='practice')await play(a);if(a==='tutorial'){forceLesson=true;await play('practice');}if(a==='lessonstart'||a==='replaylesson')startLesson();if(a==='lessonskip')skipLesson();if(a==='help')help(0,b.dataset.back||'close');if(a==='helppage')help(v,helpBack);if(a==='pause')pauseMenu();if(a==='cloud'){practiceHome=false;prefs=account.preferences;home();}if(a==='auth')openAuth();if(a==='authmode'){authMode=v;openAuth();}if(a==='garage')garage();if(a==='shop')shop();if(a==='category'){category=v;b.dataset.kind==='garage'?garage():shop();}if(a==='contracts')contracts();if(a==='journal')journal(b.dataset.back||'close');if(a==='trackIsland'){if(islandById(v)){courseIsland=v;closeModal();updateHud();toast('Marked '+islandById(v).name+' on your chart.');}}if(a==='questStart'||a==='questFinish'){send(a);closeModal();}if(a==='profile')profile();if(a==='settings')settings(b.dataset.back||undefined);if(a==='map')map();if(a==='cargo')cargo();if(a==='fleet')fleet();if(a==='anchor'||a==='interact'||a==='repair'||a==='land')send(a);
  if(a==='buy'){const i=CATALOG[v],tier=data().loadouts[data().selectedShip][i.id+'Tier']||0,price=i.kind==='upgrade'?i.base*(tier+1):i.price;openModal('A new addition.',`Unlock ${i.name} for ${price} banked gold?`,`${button('confirmbuy','Unlock for ◈ '+fmt(price),'primary',false,`data-value="${v}"`)}`,true);}
  if(a==='confirmbuy'){b.disabled=true;await action({type:'purchase',item:v});audio.play('purchase');feedback.celebrate(CATALOG[v].name+' unlocked','Visit Ship & skins to equip it.');toast('Purchase saved. Your unlock is yours.','success');shop();}if(a==='equip'){await action({type:'equip',item:v});audio.play('equip');toast('Loadout saved.','success');garage();}if(a==='accept'){await action({type:'acceptContract',id:v});contracts();}if(a==='abandon'){await action({type:'abandonContract'});contracts();}if(a==='claim'){await action({type:'claimAchievement',id:v});audio.play('achievement');profile();}if(a==='discard'){if(world)world.discard(world.ships.get(playerId),v);else room?.send('discard',v);closeModal();}
  if(a==='fleetcreate'||a==='fleetleave'){send('fleet',{type:a==='fleetcreate'?'create':'leave'});closeModal();}if(a==='fleetaccept'||a==='fleetkick'){send('fleet',{type:a==='fleetaccept'?'accept':'kick',id:v});closeModal();}if(a==='bind'){pendingBinding=v;b.textContent='Press a new key…';}if(a==='fullscreen'){if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}if(a==='finish'||a==='leave')await finish();if(a==='abandonvoyage'){const old=room;room=null;sessionStorage.removeItem('tidebound-reconnect');await old?.leave();lesson=null;lessonIntro=false;closeModal();snapshot=null;gameMode=null;home('harbor');}if(a==='logout'){if(gameMode){openModal('Finish your voyage first.','Return and bank your cargo, or end the voyage before signing out.',button('leave','End voyage','peach'),true);}else {await auth.auth.signOut();session=null;account=null;practiceHome=!configured;closeModal();home('title');}}
}catch(err){toast(err.message,'error');b.disabled=false;}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const values=Object.fromEntries(new FormData(form));const error=form.querySelector('.form-error'),submit=form.querySelector('button[type=submit],button:not([type])');if(submit)submit.disabled=true;if(error)error.textContent='';try{if(form.dataset.form==='auth'){let response;if(authMode==='signup'){values.name=cleanName(values.name);response=await auth.auth.signUp({email:values.email,password:values.password,options:{data:{pirate_name:values.name},emailRedirectTo:location.href.split('#')[0]}});}else if(authMode==='recovery')response=await auth.auth.resetPasswordForEmail(values.email,{redirectTo:location.href.split('#')[0]});else response=await auth.auth.signInWithPassword({email:values.email,password:values.password});if(response.error)throw response.error;if(authMode==='recovery'||authMode==='signup'&&!response.data.session){toast('Check your email for the account link.','success');closeModal();}else {session=response.data.session;practiceHome=false;await loadAccount();closeModal();home();}}
  if(form.dataset.form==='password'){const {error:err}=await auth.auth.updateUser({password:values.password});if(err)throw err;toast('Password updated.','success');closeModal();await loadAccount();}
  if(form.dataset.form==='profile'){await action({type:'profile',name:values.name,shipName:values.shipName});profile();toast('Names saved.','success');}
  if(form.dataset.form==='settings'){qualityOverride=values.device?values.quality:null;try{if(qualityOverride)localStorage.setItem('tidebound-quality-override',qualityOverride);else localStorage.removeItem('tidebound-quality-override');}catch{}const p={...prefs,master:Number(values.master),music:Number(values.music),effects:Number(values.effects),quality:values.device?prefs.quality:values.quality,reducedMotion:Boolean(values.motion),keys:{...prefs.keys}};if(account||practiceHome)await action({type:'preferences',value:p});else {prefs=p;audio.configure(prefs);}backFromModal();toast('Options saved.','success');}
  if(form.dataset.form==='fleet'){send('fleet',{type:'request',code:values.code});toast('Join request sent to the fleet leader.');closeModal();}
}catch(err){if(error)error.textContent=err.message;else toast(err.message,'error');}finally{if(submit)submit.disabled=false;}});
window.addEventListener('keydown',e=>{if(pendingBinding){e.preventDefault();prefs={...prefs,keys:{...prefs.keys,[pendingBinding]:e.code}};pendingBinding=null;settings(dialogBack);return;}if(e.target.matches('input,select,textarea'))return;if(modal){if(e.code==='Escape'){e.preventDefault();backFromModal();}return;}if(!gameMode){if(e.code==='Escape')home('title');if(e.code==='Enter'&&menuScreen==='title')home('voyages');return;}const p=prefs.keys;keys.add(e.code);if(Object.values(p).includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyH'&&!Object.values(p).includes(e.code)){help();return;}if(e.code==='KeyJ'&&!Object.values(p).includes(e.code)){journal();return;}for(const a of ['anchor','interact','repair','map','cargo','settings'])if(e.code===p[a]){if(['map','cargo','settings'].includes(a))({map,cargo,settings:pauseMenu}[a])();else send(a);}});
document.addEventListener('visibilitychange',()=>audio.setVisible(!document.hidden));let lastHover=0;document.addEventListener('pointerover',e=>{if(e.target.closest('button')&&!e.target.closest('button')?.contains(e.relatedTarget)&&performance.now()-lastHover>80){lastHover=performance.now();if(audio.ctx)audio.play('hover');}});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();pointer.fire=false;});window.addEventListener('pointermove',e=>{pointer.x=e.clientX;pointer.y=e.clientY;const reticle=$('.reticle');if(reticle){reticle.style.left=e.clientX+'px';reticle.style.top=e.clientY+'px';}});window.addEventListener('pointerdown',e=>{if(e.target.closest('#ocean')&&!modal&&!snapshot?.me.ashore&&[0,2].includes(e.button)){pointer.x=e.clientX;pointer.y=e.clientY;pointer.fire=true;pointer.special=e.button===2;audio.start();updateAim();send('attack',{...aimIntent,special:pointer.special});}});window.addEventListener('pointerup',()=>{pointer.fire=false;pointer.special=false;});window.addEventListener('contextmenu',e=>{if(e.target.closest('#ocean'))e.preventDefault();});
function frame(now){const dt=Math.min(.05,(now-lastFrame)/1000);lastFrame=now;feedback.update(dt);if(gameMode&&snapshot){if(now-lastInput>50){lastInput=now;updateAim();const p=prefs.keys,side=keys.has(p.fireLeft)?'left':keys.has(p.fireRight)?'right':null;const input={walkX:modal?0:Number(keys.has(p.right))-Number(keys.has(p.left)),walkY:modal?0:Number(keys.has(p.sailDown))-Number(keys.has(p.sailUp)),sail:modal?0:Number(keys.has(p.sailUp))-Number(keys.has(p.sailDown)),steer:modal?0:Number(keys.has(p.right))-Number(keys.has(p.left)),aim:aimIntent.aim,target:aimIntent.target,fire:!modal&&(pointer.fire||Boolean(side)),side,special:pointer.special};if(world)world.input(playerId,input);else room?.send('input',input);}if(world){world.tick(dt);snapshot=world.snapshot(playerId);renderer?.sync(snapshot,playerId);}audio.update(snapshot.me,dt,{paused:Boolean(modal)&&gameMode!=='online'});if(!modal)advanceLesson({steer:Number(keys.has(prefs.keys.right))-Number(keys.has(prefs.keys.left))},dt);renderer?.render(dt,now/1000);if(now-lastHud>250){lastHud=now;updateHud();}if(room&&Math.floor(now/3000)!==Math.floor((now-dt*1000)/3000)){room.send('ping',Date.now());const saved=JSON.parse(sessionStorage.getItem('tidebound-reconnect')||'null');if(saved){saved.at=Date.now();sessionStorage.setItem('tidebound-reconnect',JSON.stringify(saved));}}}else preview?.render(now/1000,prefs.reducedMotion);requestAnimationFrame(frame);}
requestAnimationFrame(frame);
async function boot(){home();if(!auth)return;auth.auth.onAuthStateChange((event,s)=>{session=s;if(event==='PASSWORD_RECOVERY')setTimeout(()=>openModal('A fresh password.','Choose a password with at least eight characters.',`<form class="form" data-form="password"><label>New password<input name="password" type="password" minlength="8" autocomplete="new-password" required></label><button class="primary">Save password</button><div class="form-error" role="alert"></div></form>`,true),0);});try{const {data:{session:s}}=await auth.auth.getSession();session=s;if(s){await loadAccount();const cached=JSON.parse(sessionStorage.getItem('tidebound-reconnect')||'null');if(cached&&cached.user===s.user.id&&Date.now()-cached.at<30000){gameMode=cached.mode;try{attachRoom(await network.reconnect(cached.token));beginOcean();}catch{gameMode=null;home();toast('The unfinished voyage ended. Banked progress is unchanged.');}}}}catch(e){saveStatus='Account loading failed';home();toast(e.message,'error');}}
boot();
